allf={"characters":characters,"ancients":ancients,"card_keywords":card_keywords,"relics":relics,"powers":powers,"cards":cards}
for fn,d in allf.items(): save(fn,d)
TAGS=("[gold]","[/gold]","[blue]","[/blue]","[red]","[/red]")
ok=True
for fn,d in allf.items():
    e=le(fn)
    if set(e)!=set(d): ok=False; print(f"[{fn}] claves: faltan {set(e)-set(d)} extra {set(d)-set(e)}")
    for k in e:
        if k not in d: continue
        ev,sv=e[k],d[k]
        for t in TAGS:
            if ev.count(t)!=sv.count(t): ok=False; print(f"[{fn}] {k}: tag {t} {ev.count(t)}!={sv.count(t)}")
        if ev.count("{")!=sv.count("{") or ev.count("}")!=sv.count("}"): ok=False; print(f"[{fn}] {k}: llaves {ev.count('{')}/{ev.count('}')} vs {sv.count('{')}/{sv.count('}')}")
        et=sorted(re.findall(r'\{[A-Za-z][A-Za-z0-9]*(?::[a-zA-Z]+\(\))?\}',ev)); st=sorted(re.findall(r'\{[A-Za-z][A-Za-z0-9]*(?::[a-zA-Z]+\(\))?\}',sv))
        if et!=st: ok=False; print(f"[{fn}] {k}: tokens {et}!={st}")
        if ev.count("\n")!=sv.count("\n"): ok=False; print(f"[{fn}] {k}: saltos {ev.count(chr(10))}!={sv.count(chr(10))}")
print("RIENSANG v1.0.2 VALIDACION OK" if ok else "REVISAR ^")
